import React, { useState } from 'react';

const Login = () => {
  const [formData, setFormData] = useState({
    userId: '',
    password: '',
    role: '',
  });
  const [error, setError] = useState('');

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
    setError('');
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    const { userId, password, role } = formData;

    // Basic validation
    if (!userId || !password || !role) {
      setError('Please fill in all fields.');
      return;
    }

    // TODO: Replace with real API call in later step
    console.log('Logging in:', formData);

    // Temporary role-based redirect (we'll wire this properly in Step 4)
    const routes = {
      patient:    '/patient/dashboard',
      doctor:     '/doctor/dashboard',
      pharmacist: '/pharmacist/dashboard',
      admin:      '/admin/dashboard',
    };

    alert(`Redirecting to ${routes[role]}`); // placeholder for now
  };

  return (
    <div
      className="d-flex align-items-center justify-content-center"
      style={{ minHeight: '100vh', backgroundColor: 'var(--bg)' }}
    >
      <div className="card-custom" style={{ width: '100%', maxWidth: '420px' }}>

        {/* Header */}
        <div className="text-center mb-4">
          <div style={{ fontSize: '2.5rem' }}>🏥</div>
          <h1 style={{ fontSize: '1.3rem', fontWeight: 700, marginTop: '0.5rem' }}>
            University Health Centre
          </h1>
          <p style={{ color: 'var(--muted)', fontSize: '0.9rem' }}>
            Medication Reminder System
          </p>
        </div>

        {/* Form */}
        <form onSubmit={handleSubmit} noValidate>

          {/* ID Field */}
          <div className="mb-3">
            <label className="form-label fw-semibold">Student / Staff ID</label>
            <input
              type="text"
              name="userId"
              className="form-control"
              placeholder="e.g. STU/2024/001"
              value={formData.userId}
              onChange={handleChange}
            />
          </div>

          {/* Password Field */}
          <div className="mb-3">
            <label className="form-label fw-semibold">Password</label>
            <input
              type="password"
              name="password"
              className="form-control"
              placeholder="Enter your password"
              value={formData.password}
              onChange={handleChange}
            />
          </div>

          {/* Role Dropdown */}
          <div className="mb-4">
            <label className="form-label fw-semibold">Login as</label>
            <select
              name="role"
              className="form-select"
              value={formData.role}
              onChange={handleChange}
            >
              <option value="">-- Select your role --</option>
              <option value="patient">Patient</option>
              <option value="doctor">Doctor</option>
              <option value="pharmacist">Pharmacist</option>
              <option value="admin">Admin</option>
            </select>
          </div>

          {/* Error Message */}
          {error && (
            <div className="alert alert-danger py-2 mb-3" role="alert">
              {error}
            </div>
          )}

          {/* Submit */}
          <button type="submit" className="btn-primary-custom">
            Login
          </button>

        </form>
      </div>
    </div>
  );
};

export default Login;
